// Real account API, fake account data, no trader or execution loop.
require('ts-node/register');
const { acquireEngineLock } = require('../../src/core/engineLock');
const release = acquireEngineLock(process.env.DATA_DIR);
process.once('exit', release);
const { config } = require('../../src/core/config');
config.api.port = Number(process.env.TEST_ENGINE_PORT || 0);
const { HeadlessUI } = require('../../src/ui/headless');
const { startApiServer } = require('../../src/server/api');
const { loadPolicy } = require('../../src/policy/load');
const { updateState } = require('../../src/state/state');
const { recordTick } = require('../../src/features/lastTick');
const { createAction } = require('../../src/core/actions');
const { closeStorage } = require('../../src/core/storage');
loadPolicy(); updateState({ accountId: 'alpaca:paper:process-test', paused: false });
const ui = new HeadlessUI();
ui.setEnvironment({ broker: 'alpaca', venue: 'paper', provider: 'test', model: 'test' });
ui.setTraderActivity({ state: 'sleeping', detail: 'Process test engine' });
ui.registerCommand({ name: 'pause', api: true, help: 'Pause trading', run: () => updateState({ paused: true }) });
ui.registerCommand({ name: 'resume', api: true, help: 'Resume trading', run: () => updateState({ paused: false }) });
const action = createAction({ kind: 'entry', symbol: 'AAPL', venue: 'paper', params: { qty: 1, signal: { price: 100, stopLoss: 95, takeProfit: 110 } }, reason: 'Process isolation test', timeoutMs: 600000 });
const tick = { tickAt: new Date().toISOString(), positionsStale: false, ordersStale: false, positions: {}, orders: [], watchlist: {}, account: { equity: 10000, cash: 10000 }, portfolio: {}, session: 'closed' };
recordTick(tick); ui.setTick(tick); ui.log('INFO', 'Engine process ready');
ui.showChart({kind:'price',label:'AAPL',values:[100,102,101],dates:['2026-10-06','2026-10-07','2026-10-08']});
const server = startApiServer({ ui, serveWeb: false, trader: { status: { paused: false } } });
setImmediate(() => process.send({ ready: true, port: server.address().port, actionId: action.id }));
let stopping = false;
const stop = async () => { if (stopping) return; stopping = true; await server.close(); closeStorage(); release(); process.disconnect(); };
process.on('SIGTERM', stop); process.on('message', message => { if (message === 'stop') void stop(); });
